import {localGifPaths,localStickerPaths} from './local-media-index.js';
import {dragonFileId} from './dragongif.js';
// IDs are absolute, same-origin URLs generated by the local-media indexer.
export const localGif = value=>localGifPaths.has(value)||!!dragonFileId(value);
export const localSticker = value=>localStickerPaths.has(value)||!!dragonFileId(value);
const frameDefaults={x:50,y:50,zoom:100};
export function localAvatar(value){
 if(typeof value!=='string')return null;
 const [path,query,...rest]=value.split('?');
 if(rest.length||!localGif(path))return null;
 let frame={...frameDefaults};
 if(query!==undefined){
  const match=/^x=(\d{1,3}(?:\.\d)?)&y=(\d{1,3}(?:\.\d)?)&zoom=(\d{1,3}(?:\.\d)?)$/.exec(query);
  if(!match)return null;
  frame={x:Number(match[1]),y:Number(match[2]),zoom:Number(match[3])};
  if(frame.x<0||frame.x>100||frame.y<0||frame.y>100||frame.zoom<100||frame.zoom>300)return null;
 }
 return {path,frame};
}
export function localAvatarMarker(path,frame=frameDefaults){
 if(!localGif(path))return null;
 const {x,y,zoom}=frame;
 if(![x,y,zoom].every(Number.isFinite)||x<0||x>100||y<0||y>100||zoom<100||zoom>300)return null;
 return `${path}?x=${x}&y=${y}&zoom=${zoom}`;
}
export const storedAvatarFrame=user=>localAvatar(user.avatar_url)?.frame||{x:user.avatar_x??50,y:user.avatar_y??50,zoom:user.avatar_zoom??100};
